class BaseA { int x; };
class BaseB { int y; };

// Multiple Inheritance Layout
class Derived : public BaseA, public BaseB {};

Derived d;
Derived* d_ptr = &d;

// Upcast 1 (BaseA often requires no pointer adjustment)
BaseA* a_ptr = d_ptr;

// Upcast 2 (BaseB requires internal pointer adjustment/offset)
BaseB* b_ptr = static_cast<BaseB*>(d_ptr);

// Addresses usually differ: (void*)a_ptr != (void*)b_ptr
// d_ptr == a_ptr, but b_ptr is offset.
